private Map<String, Object> timeline(String sessionId, Map<String, String> query) {
    int limit = query.containsKey("limit") ? integer(query.get("limit")) : 50;
    if (limit < 1 || limit > 200) throw invalid("timeline_limit_out_of_range");
    List<Message> messages = sessions.transcript(sessionId);
    long before = query.containsKey("cursor")
            ? decodeTimelineCursor(query.get("cursor"), sessionId) : messages.size();
    int end = Math.toIntExact(Math.min(before, messages.size()));
    int start = Math.max(0, end - limit);
    List<Map<String, Object>> items = new ArrayList<>();
    for (int index = start; index < end; index++) {
        Map<String, Object> item = new java.util.LinkedHashMap<>(message(messages.get(index)));
        item.put("sequence", index + 1L);
        item.put("key", messages.get(index).id());
        items.add(Map.copyOf(item));
    }
    return Map.of(
            "items", List.copyOf(items),
            "olderCursor", start > 0 ? encodeTimelineCursor(sessionId, start) : "",
            "newerCursor", "");
}

